WITH with_dims AS (SELECT s.*, p.name, p.country, p.signup_date FROM accounts s LEFT JOIN customers p ON s.customer_id = p.id) SELECT account_type, CASE WHEN balance >= 75000 THEN 'HIGH' ELSE 'LOW' END AS balance_tier, COUNT_IF(account_type = 'SAVINGS') AS savings_events, COUNT(DISTINCT country) AS distinct_countries, MAX(balance) AS max_balance, GROUPING_ID() AS gid FROM with_dims GROUP BY CUBE (account_type, CASE WHEN balance >= 75000 THEN 'HIGH' ELSE 'LOW' END) ORDER BY max_balance DESC NULLS LAST
